* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 0 0 28px;
     font-family: Arial, "Segoe UI", sans-serif;
     background: #f5f7f4;
}

.khung-trang {
     max-width: 1000px;
     margin: 0 auto;
     background: #ffffff;
     box-shadow: 0 0 28px rgba(0, 0, 0, 0.1);
}

header {
    background: #2E7D32;
    color: #FFEB3B;
    text-align: center;
    padding: 18px;
}

header h1 { margin: 0; font-size: 24px; }

.dan-nhap {
    margin: 0;
    padding: 14px 24px;
    color: #1b5e20;
    font-style: italic;
    border-bottom: 1px solid #e0e6df;
}

.luoi-ky-quan {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    padding: 20px 24px;
}

.the {
    border: 1px solid #e0e6df;
    border-radius: 8px;
    overflow: hidden;
    background: #ffffff;
}

.the img {
    width: 100%;
    height: 150px;
    object-fit: cover;
    display: block;
    border-bottom: 3px solid #2E7D32;
}

  .the h2 {
      margin: 12px 14px 6px;
      color: #1b5e20;
      font-size: 16px;
  }

  .the p {
      margin: 0 14px 14px;
      font-size: 13px;
      line-height: 1.5;
      color: #333333;
  }

  @media (max-width: 768px) {
      .luoi-ky-quan { grid-template-columns: repeat(2, 1fr); }
  }

  @media (max-width: 480px) {
      .luoi-ky-quan { grid-template-columns: 1fr; }
  }
